				\usepackage{mathrsfs}
				\usepackage{upgreek}
				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$$\begin{array}{l}\rm{Haemolysis}\;( \% )\\=\displaystyle\frac{100{\rm{\times }}({{absorbance}}_{405\;{nm\; peptide}}-{{absorbance}}_{405\;{nm\; negative\; control}})}{({absorbance}_{405\;{nm\; positive\; control}}-{{absorbance}}_{405\;{nm\; negative\; control}})}\end{array}$$\end{document}Haemolysis(%)=100×(absorbance405nmpeptide−absorbance405nmnegativecontrol)(absorbance405nmpositivecontrol−absorbance405nmnegativecontrol)
